<?php
declare(strict_types=1);require_once __DIR__.'/billing_common.php';$user=billing_require_admin();production_require_method('GET');accounts_endpoint(function():array{$db=production_db();$client=(int)($_GET['client_id']??0);$sql="SELECT ps.id AS production_session_id,ps.client_id,ps.project_id,ps.project_site,pr.report_no,sg.total_m3 AS signed_m3,CONCAT(ps.mixer_code_snapshot,' ',ps.mixer_name_snapshot) mixer,COALESCE((SELECT SUM(pa.billed_m3) FROM qbook_invoice_production_allocations pa WHERE pa.production_session_id=ps.id AND pa.status='COMMITTED'),0)-COALESCE((SELECT SUM(cl.released_m3) FROM qbook_credit_note_lines cl JOIN qbook_credit_notes cn ON cn.id=cl.credit_note_id AND cn.status='ISSUED' JOIN qbook_invoice_lines il ON il.id=cl.invoice_line_id JOIN qbook_invoice_production_allocations pa2 ON pa2.invoice_line_id=il.id WHERE pa2.production_session_id=ps.id AND cl.quantity_treatment='RELEASE_QUANTITY'),0) billed_m3 FROM qbook_production_sessions ps JOIN qbook_production_reports pr ON pr.production_session_id=ps.id JOIN qbook_production_signoffs sg ON sg.production_session_id=ps.id WHERE ps.status='SIGNED'".($client>0?' AND ps.client_id=?':'')." HAVING signed_m3>billed_m3 ORDER BY ps.production_date,ps.id";$s=$db->prepare($sql);$s->execute($client>0?[$client]:[]);$rows=[];foreach($s->fetchAll()as$r){$r['reference']=production_report_reference((int)$r['report_no']);$r['available_m3']=number_format((float)$r['signed_m3']-(float)$r['billed_m3'],2,'.','');$rows[]=$r;}return['reports'=>$rows];});
